//! 🧩️ Original graph identities and complete value forests share one admitted relational prefix.
use super::{SemioValueSnapshot,SemioValue,SemioValueNode,ValueId,ValueSqliteTables,VALUE_TABLES,identity};
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,artifact::{RowIndex,RowIndexStorage,reconstruct_text_into},transfer::{SchemaValidationStorage,validate_database_into,validate_component_into,reserve}}};
use semio_framework_value::{ValueError,ValueRefusalKind};
#[path="🌳️forest/🦀️.rs"]
pub mod forest;
pub use forest::{ValueForestStorage,reconstruct_value_forest_into};
#[derive(semio_framework_value::RetireOwned)]
struct Prefix{snapshot:Option<SemioValueSnapshot>,validation:SchemaValidationStorage,nodes:RowIndexStorage,order:Vec<usize>,names:Vec<usize>,roots:Vec<i64>,forest:ValueForestStorage}
fn empty()->Prefix{Prefix{snapshot:Some(super::native_decoding::empty()),validation:SchemaValidationStorage::empty(),nodes:RowIndexStorage::empty(),order:Vec::new(),names:Vec::new(),roots:Vec::new(),forest:ValueForestStorage::empty()}}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
pub(super)fn reconstruct(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,declared:&str)->Result<SemioValueSnapshot,ValueError>{crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding::workspace::reconstruct_projected(control,empty,|prefix,control|{
 let phase=SqliteSnapshotPhase::ReconstructSnapshot;control.check_database(database,phase)?;validate_database_into(&mut prefix.validation,database,declared,phase,control)?;validate_component_into(&mut prefix.validation,database,SemioValueSnapshot::SQLITE_SCHEMA,phase,control)?;let document=database.table("semio_value_document")?.single_row()?;identity(document,3)?;if document.rowid!=1{return Err(invalid("Semio value document requires identifier 1"))}let nodes=RowIndex::new(&mut prefix.nodes,database,"semio_value_node",5,&[],control,"invalid Semio value graph node")?;nodes.ordered_into(&mut prefix.order,2,control,"Semio value node ordinals must be contiguous")?;nodes.unique_text(&mut prefix.names,nodes.indices(),3,control,"invalid Semio value graph node")?;for(count,&index)in nodes.indices().iter().enumerate(){if nodes.row(index)?.integer(1)?!=1{return Err(invalid("invalid Semio value graph node"))}control.checkpoint(phase,count+1,nodes.len())?;}
 let count=prefix.order.len().checked_add(1).ok_or_else(||invalid("Semio value root count overflow"))?;prefix.roots=reserve(count,control)?;prefix.roots.push(document.integer(2)?);for(count,&index)in prefix.order.iter().enumerate(){prefix.roots.push(nodes.row(index)?.integer(4)?);control.checkpoint(phase,count+1,prefix.order.len())?;}reconstruct_value_forest_into(&mut prefix.forest,database,VALUE_TABLES,&prefix.roots,Some(&nodes),control)?;let snapshot=prefix.snapshot.as_mut().unwrap();snapshot.nodes=reserve(prefix.order.len(),control)?;snapshot.root=prefix.forest.take_root(0)?;
 for(ordinal,&index)in prefix.order.iter().enumerate(){let row=nodes.row(index)?;snapshot.nodes.push(SemioValueNode{id:ValueId{value:String::new()},value:SemioValue::Null});let node=snapshot.nodes.last_mut().unwrap();reconstruct_text_into(&mut node.id.value,control,row.text(3)?)?;node.value=prefix.forest.take_root(ordinal+1)?;control.checkpoint(phase,ordinal+1,nodes.len())?;}if !prefix.forest.roots_consumed(){return Err(invalid("unclaimed Semio value reconstructed root"))}reconstruct_text_into(&mut snapshot.schema,control,document.text(1)?)?;control.checkpoint(phase,count,count)
},|prefix|prefix.snapshot.take().unwrap())}
